/* Bingkai tipis dekoratif di sekeliling halaman */
.frame-outer {
  position: fixed;
  top: 22px; left: 22px; right: 22px; bottom: 22px;
  border: 1.5px solid #d4af37;
}
.frame-inner {
  position: fixed;
  top: 27px; left: 27px; right: 27px; bottom: 27px;
  border: 0.75px solid #0F2C59;
}

/* Pita dekoratif sudut - position:fixed, tidak ikut alur/tinggi konten */
.ribbon-tl {
  position: fixed;
  top: 0; left: 0;
  width: 260px; height: 260px;
}
.ribbon-br {
  position: fixed;
  bottom: 0; right: 0;
  width: 260px; height: 260px;
}

/* Konten utama - lebar persentase (bukan px tetap) supaya selalu center
   walau dimensi kanvas dompdf sedikit berbeda dari asumsi. */
.content {
  display: inline-block;
  width: 820px;
  box-sizing: border-box;
  padding-top: 165px;
  text-align: center;
}
.logo { width:140px; height:auto; margin:0 auto 4px; display:block; }

.cert-title {
  font-weight: 700;
  font-size: 40px;
  color: #0F2C59;
